#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The fresh Pi 5 wizard: from a blank SD card to a Pi this laptop reaches over SSH. pi/wizard.sh then runs the sessions.
#
#   bash pi/provision.sh          from Git Bash on the laptop
#
# It has Imager write Raspberry Pi OS (Legacy, 64-bit) Lite, which is PLATFORMS.md's Bookworm with Python 3.11, with
# this laptop's SSH key on the card. It then connects, checks the board and records its facts in
# verification/pi5_facts.txt. The host and the user go into pi/.env, where pi/wizard.sh reads them. Run it again at any
# time: when the card is already written and the Pi booted from it, stage 1 skips to the connection.

run_wizard() {

TOTAL_STAGES=9

STUDY="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$STUDY"
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE="$STUDY/pi/.env"
FACTS="verification/pi5_facts.txt"
KEY="$HOME/.ssh/id_ed25519"
HOTSPOT="ms-settings:network-mobilehotspot"
die()  { warn "$1"; exit 1; }
next() { pause "Press Enter for the next stage"; }
good() { say "${GREEN}✓${RESET} $1"; }
BAD=0
bad()  { warn "$1"; BAD=$((BAD + 1)); }

# ssh_try HOST: SSH with this laptop's key alone works. A fresh card's host key is accepted; SSH_ERR keeps ssh's message.
SSH_ERR=""
ssh_try() {
  SSH_ERR=$(ssh -n -o BatchMode=yes -o ConnectTimeout=8 -o StrictHostKeyChecking=accept-new "$PI_USER@$1" true 2>&1 >/dev/null) && return 0
  return 1
}
# reach HOST: ssh_try, and when the Pi answers but refuses the key, offer to copy the key with the Pi's password (once).
NO_COPY=""
reach() {
  ssh_try "$1" && return 0
  [[ "$SSH_ERR" == *"Permission denied"* && -z "$NO_COPY" ]] || return 1
  printf '\n'
  warn "$1 answers, but does not take this laptop's key (Imager's SSH may be set to a password)."
  confirm "Copy the key there now, with the Pi's password?" || { NO_COPY=1; return 1; }
  ssh-copy-id -o StrictHostKeyChecking=accept-new -i "$KEY.pub" "$PI_USER@$1" || true
  ssh_try "$1"
}
# forget_key HOST drops a saved host key for HOST: a freshly written card has new host keys, so a saved one is stale.
forget_key() {
  if ssh-keygen -F "$1" >/dev/null 2>&1; then
    ssh-keygen -R "$1" >/dev/null 2>&1 || true
    note "removed the old host key for $1 from ~/.ssh/known_hosts (the new card has new ones)"
  fi
}
# find_pi prints the IPs, on this laptop's hotspot or home network, whose network card is a Raspberry Pi's (Raspberry
# Pi Ltd's MAC prefixes): it pings every address of each /24 once, so the ARP table learns who is there. The VPNs'
# addresses (Tailscale 100.x, WARP 172.16.x) are not swept; on the laptop's hotspot only its own 192.168.137.x is.
PI_OUIS='2c-cf-67|d8-3a-dd|dc-a6-32|e4-5f-01|b8-27-eb|28-cd-c1|88-a2-9e'
find_pi() {
  local nets s i
  if [[ "$PI_NET" == 1 ]]; then
    nets="192.168.137"
  else
    nets=$(ipconfig 2>/dev/null | tr -d '\r' | sed -n 's/.*IPv4 Address[. ]*: *\([0-9.]*\).*/\1/p' \
           | grep -E '^(192\.168\.|10\.|172\.20\.10\.)' | cut -d. -f1-3 | sort -u || true)
  fi
  for s in $nets; do
    for i in $(seq 254); do ping -n 1 -w 400 "$s.$i" >/dev/null 2>&1 & done
    wait
  done
  arp -a 2>/dev/null | tr -d '\r' | grep -iE "$PI_OUIS" | awk '{print $1}' | sort -u || true
}
# search_pi: find_pi, then SSH to each Pi found; HOST is the one that takes this laptop's key.
search_pi() {
  local ip
  say "Looking for a Raspberry Pi on the network (about 15 s)..."
  while IFS= read -r ip; do
    if [[ -n "$FRESH" ]]; then forget_key "$ip"; fi
    if reach "$ip"; then HOST="$ip"; good "found it at $ip"; return 0; fi
    note "a Raspberry Pi at $ip does not answer SSH with this laptop's key: $(printf '%s\n' "${SSH_ERR:-}" | tail -n1)"
  done < <(find_pi)
  return 1
}
find_imager() {
  local p
  for p in "/c/Program Files/Raspberry Pi Imager/rpi-imager.exe" "/c/Program Files (x86)/Raspberry Pi Imager/rpi-imager.exe"; do
    [[ -f "$p" ]] && { printf '%s' "$p"; return 0; }
  done
  return 1
}

banner "A fresh Pi 5: from a blank SD card to SSH"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "What you need"
say "This wizard sets the Pi 5 up from a blank SD card. Then pi/wizard.sh takes it through the sessions."
say "Have these ready:"
step "The Pi 5, its official 27 W USB-C supply, and the fan's 4-pin plug in the socket printed FAN."
step "A microSD card of 32 GB or more, and a card reader for this laptop. The matrix's detections alone take about 6 GB."
step "About 30 minutes. Writing the card takes 5-10 of them."
FRESH=1
if confirm "Is the card already written, and the Pi booted from it? (yes skips to the connection)"; then
  FRESH=""
  _STAGE_INDEX=6
else
  warn "Writing the card erases everything on it."
  confirm "Ready to write the card?" || { say "Run it again when you are: bash pi/provision.sh"; exit 0; }
fi

if [[ -n "$FRESH" ]]; then

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Raspberry Pi Imager on this laptop"
IMAGER=$(find_imager || true)
if [[ -z "$IMAGER" ]]; then
  say "Imager is not installed yet."
  open_url "https://www.raspberrypi.com/software/"
  step "Click 'Download for Windows', run the installer and keep its defaults."
  pause "Press Enter once Imager is installed"
  IMAGER=$(find_imager || true)
fi
if [[ -n "$IMAGER" ]]; then
  say "Imager: $IMAGER"
else
  warn "Imager is not in Program Files. If you installed it somewhere else, open it from the Start menu in stage 5."
fi
next

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The network the Pi joins"
say "The Pi joins a network this laptop is on, with internet: pi/wizard.sh's install downloads the pinned packages."
note "Campus Wi-Fi that asks for a user name (such as amritanet.edu) does not work: the Pi cannot log in to it."
say "  1) this laptop's Mobile Hotspot, as for the phone. Recommended."
say "  2) a home Wi-Fi with a plain password, that this laptop is on too."
ask PI_NET "Which one, 1 or 2?"
[[ "$PI_NET" == 1 || "$PI_NET" == 2 ]] || die "answer 1 or 2: run the wizard again"
write_env PI_NET "$PI_NET"
if [[ "$PI_NET" == 1 ]]; then
  open_url "$HOTSPOT"
  step "Turn Mobile hotspot on."
  step "Under Properties, click Edit, and note the network's name and password."
  step "Turn Power saving off, so the hotspot stays on while the Pi is the only device on it."
  note "Keep the hotspot on whenever you work with the Pi."
else
  step "Have the Wi-Fi's name and password ready, and check that this laptop is on that Wi-Fi."
fi
pause "Press Enter when you have the network's name and password"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The Pi's name, its user and this laptop's SSH key"
ask PI_NAME "A host name for the Pi (letters, digits and hyphens; Enter for pi5):" || PI_NAME=""
[[ -n "$PI_NAME" ]] || PI_NAME=pi5
[[ "$PI_NAME" =~ ^[A-Za-z0-9-]+$ ]] || die "a host name has letters, digits and hyphens only: run the wizard again"
ask PI_USER "The user to make on the Pi (lower case; Enter for pi):" || PI_USER=""
[[ -n "$PI_USER" ]] || PI_USER=pi
[[ "$PI_USER" =~ ^[a-z_][a-z0-9_-]*$ ]] || die "a user name has lower-case letters, digits, - and _ only: run the wizard again"
write_env PI_NAME "$PI_NAME"
write_env PI_USER "$PI_USER"
if [[ -f "$KEY.pub" ]]; then
  say "This laptop's SSH key: $KEY.pub"
else
  confirm "Make an SSH key on this laptop ($KEY, no passphrase)?" || die "Imager needs a public key for SSH: run the wizard again"
  ssh-keygen -t ed25519 -N "" -f "$KEY"
fi
note "Imager writes its public half onto the card, so SSH works at the first boot with no password."
note "You choose the user's password in Imager. This wizard never asks for it: keep it for sudo."
next

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Write the SD card with Imager"
step "Put the SD card in this laptop's reader."
if [[ -n "$IMAGER" ]] && powershell.exe -NoProfile -Command "Start-Process -FilePath '$(cygpath -w "$IMAGER")'" >/dev/null 2>&1; then
  say "Opening Imager. Windows asks whether it may make changes: Yes."
else
  step "Open Raspberry Pi Imager from the Start menu."
fi
if clip.exe < "$KEY.pub" 2>/dev/null; then
  note "This laptop's public key is on the clipboard, for the Remote access step."
else
  note "This laptop's public key, for the Remote access step: $(cat "$KEY.pub")"
fi
say "In Imager:"
step "Device: Raspberry Pi 5. Next."
step "OS: Raspberry Pi OS (other) → Raspberry Pi OS (Legacy, 64-bit) Lite, 'A port of Debian Bookworm ... no desktop'. Next."
note "  Not the first entry, Raspberry Pi OS (64-bit): that is Trixie, with Python 3.13 and a desktop. PLATFORMS.md's"
note "  pinned packages are for Bookworm's Python 3.11, and both Pis run the same image (#8). Not '32-bit' either."
step "Storage: the SD card. Check its size, and never pick a disk you do not recognise. Next."
step "Customisation, Hostname: $PI_NAME"
step "Customisation, Localisation: New Delhi (the time zone and the Wi-Fi country)."
step "Customisation, User: $PI_USER, with a password you will remember."
step "Customisation, Wi-Fi: the network's name and password from stage 3."
step "Customisation, Remote access: Enable SSH, with public-key authentication. Paste the key (Ctrl+V) unless Imager shows it already."
step "Customisation, Raspberry Pi Connect: leave it off."
step "Write. Confirm that the card is erased, and wait for the write and its verification. Then take the card out."
pause "Press Enter when the card is written and out of the laptop"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "First boot"
step "Put the card in the Pi's slot, on the underside of the board."
step "Check that the fan's plug is in the FAN socket: the firmware starts only a fan that is there at boot."
step "Plug in the 27 W supply. No screen or keyboard is needed."
note "The first boot grows the file system and reboots once: it takes 2-3 minutes."
if [[ "$PI_NET" == 1 ]]; then note "Once it has joined, the hotspot's settings list '$PI_NAME' under the connected devices."; fi
pause "Press Enter once it is powered on"

fi   # FRESH: stages 2-6

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Connect over SSH"
[[ -n "${PI_NAME:-}" ]] || PI_NAME=$(_existing PI_NAME || true)
[[ -n "${PI_USER:-}" ]] || PI_USER=$(_existing PI_USER || true)
[[ -n "${PI_NET:-}" ]]  || PI_NET=$(_existing PI_NET || true)
[[ -n "$PI_NAME" && -n "$PI_USER" ]] || die "no host name or user in pi/.env yet: run the wizard again and write the card (no in stage 1)"
CANDS=("$PI_NAME.local")
OLD=$(_existing PI_HOST || true)
if [[ -n "$OLD" && "$OLD" != "$PI_NAME.local" ]]; then CANDS+=("$OLD"); fi
if [[ -n "$FRESH" ]]; then for h in "${CANDS[@]}"; do forget_key "$h"; done; fi
HOST=""
say "Trying $PI_USER@${CANDS[*]} for about 3 minutes (the first boot may still be running)..."
for _ in $(seq 18); do
  for h in "${CANDS[@]}"; do
    if reach "$h"; then HOST="$h"; break 2; fi
  done
  printf '.'
  sleep 10
done
printf '\n'
if [[ -z "$HOST" ]]; then search_pi || true; fi
while [[ -z "$HOST" ]]; do
  warn "no SSH yet: $(printf '%s\n' "${SSH_ERR:-no answer}" | tail -n1)"
  if [[ "$SSH_ERR" == *"IDENTIFICATION HAS CHANGED"* ]] \
     && confirm "The Pi's host keys changed (a newly written card?). Forget the old ones for ${CANDS[*]} and try again?"; then
    for h in "${CANDS[@]}"; do forget_key "$h"; done
    for h in "${CANDS[@]}"; do
      if reach "$h"; then HOST="$h"; break; fi
    done
    if [[ -n "$HOST" ]]; then break; fi
  fi
  if [[ "$PI_NET" == 1 ]]; then
    open_url "$HOTSPOT"
    step "Find '$PI_NAME' under the hotspot's connected devices, and its IP address (192.168.137.x)."
  else
    step "Find the Pi's IP address in your router's list of devices."
  fi
  note "Not listed after 5 minutes? The Wi-Fi name or password on the card is wrong: run the wizard again and write the card."
  ask PI_IP "The Pi's IP address (Enter searches the network again; q stops here):" || PI_IP=q
  [[ "$PI_IP" != q ]] || die "no connection yet: run bash pi/provision.sh again (yes in stage 1 skips to here)"
  if [[ -z "$PI_IP" ]]; then search_pi || true; continue; fi
  if [[ -n "$FRESH" ]]; then forget_key "$PI_IP"; fi
  if reach "$PI_IP"; then HOST="$PI_IP"; fi
done
write_env PI_HOST "$HOST"
good "SSH with the key works: $PI_USER@$PI_HOST"
next

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check the Pi"
say "Reading the board, the OS and the network on the Pi..."
FACT=$(ssh -o ConnectTimeout=10 "$PI_USER@$PI_HOST" 'bash -s' <<'EOF' | tr -d '\r'
echo "date=$(date -Is)"
echo "model=$(tr -d '\0' < /proc/device-tree/model)"
. /etc/os-release; echo "os=$PRETTY_NAME"; echo "codename=$VERSION_CODENAME"
echo "image=$(head -n1 /etc/rpi-issue 2>/dev/null)"
echo "arch=$(uname -m)"
echo "kernel=$(uname -r)"
echo "python=$(python3 -c 'import platform; print(platform.python_version())')"
echo "firmware=$(vcgencmd version 2>/dev/null | paste -sd ' ' -)"
echo "bootloader=$(vcgencmd bootloader_version 2>/dev/null | head -n1)"
echo "ram_mb=$(free -m | awk '/^Mem:/ {print $2}')"
echo "fan_rpm=$(cat /sys/devices/platform/cooling_fan/hwmon/hwmon*/fan1_input 2>/dev/null | head -n1)"
echo "temp=$(vcgencmd measure_temp 2>/dev/null | cut -d= -f2)"
echo "throttled=$(vcgencmd get_throttled 2>/dev/null | cut -d= -f2)"
echo "sd_gb=$(df -BG --output=size / | tail -n1 | tr -dc 0-9)"
echo "sd_free_gb=$(df -BG --output=avail / | tail -n1 | tr -dc 0-9)"
echo "clock_synced=$(timedatectl show -p NTPSynchronized --value 2>/dev/null)"
echo "internet=$(curl -s -o /dev/null -m 15 -w '%{http_code}' https://pypi.org/simple/ 2>/dev/null)"
if python3 -m venv /tmp/provision-venv >/dev/null 2>&1; then echo "venv=ok"; else echo "venv=missing"; fi
rm -rf /tmp/provision-venv
echo "sudo_nopasswd=$(sudo -n true 2>/dev/null && echo yes || echo no)"
EOF
) || die "lost the connection to the Pi: run the wizard again (yes in stage 1 skips to the connection)"
fact() { printf '%s\n' "$FACT" | sed -n "s/^$1=//p"; }

M=$(fact model)
if [[ "$M" == *"Raspberry Pi 5"* ]]; then good "Board: $M, $(fact ram_mb) MB RAM"; else bad "Board: $M. This is not a Pi 5"; fi
if [[ "$(fact codename)" == bookworm && "$(fact arch)" == aarch64 ]]; then
  good "OS: $(fact os), 64-bit ($(fact image))"
else
  bad "OS: $(fact os) on $(fact arch). Write the card again with Raspberry Pi OS (Legacy, 64-bit) Lite"
fi
if [[ "$(fact python)" == 3.11.* ]]; then good "Python $(fact python)"; else bad "Python $(fact python), not 3.11: PLATFORMS.md's pins are for 3.11"; fi
FAN=$(fact fan_rpm)
if [[ -n "$FAN" ]]; then
  good "Fan on the FAN socket: about $FAN rpm (0 is normal while the CPU is below 50 C)"
else
  bad "No fan found. On the Pi, run 'sudo poweroff', unplug it, check the fan's plug in the FAN socket, power it on, then run this wizard again (yes in stage 1)"
fi
T=$(fact throttled)
if [[ "$T" == 0x0 ]]; then
  good "Power and throttling: clean (CPU $(fact temp))"
else
  bad "get_throttled is ${T:-unreadable}. Under-voltage (bits 0 and 16) means the supply is not the official 27 W one"
fi
SD=$(fact sd_gb)
if (( ${SD:-0} >= 28 )); then
  good "SD card: $SD GB, $(fact sd_free_gb) GB free"
else
  bad "SD card: ${SD:-?} GB. The matrix's detections need about 6 GB, beside the exports and the images: 32 GB or more is safer"
fi
if [[ "$(fact internet)" == 200 ]]; then
  good "Internet: the Pi reaches PyPI"
else
  bad "The Pi cannot reach PyPI (HTTP $(fact internet)), and pi/wizard.sh's install needs it. Is the network sharing this laptop's internet?"
fi
if [[ "$(fact clock_synced)" == yes ]]; then
  good "Clock synced: $(fact date)"
else
  warn "The clock is not synced yet ($(fact date)). It syncs over the internet; the sessions' timestamps come from it."
fi
if [[ "$(fact venv)" == ok ]]; then
  good "python3 -m venv works"
else
  warn "python3 -m venv does not work: the python3-venv package is missing."
  if confirm "Install it on the Pi now (sudo apt-get, needs internet)?" \
     && ssh -t "$PI_USER@$PI_HOST" "sudo apt-get update && sudo apt-get install -y python3-venv"; then
    good "python3-venv installed"
  else
    bad "python3-venv is missing, and pi/wizard.sh's install needs it"
  fi
fi
{ printf '# The Pi 5 after a fresh card (pi/provision.sh)\n'; printf '%s\n' "$FACT"; } > "$FACTS"
note "Recorded in study/$FACTS."
if (( BAD )); then
  warn "$BAD check(s) above need fixing before the sessions."
  confirm "Go on to the hand-over anyway?" || { say "Fix them, then run the wizard again (yes in stage 1 skips to the connection)."; exit 1; }
fi
next

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Hand over to the session wizard"
say "The Pi is ready for pi/wizard.sh. Its first run installs the pinned packages (about 10 minutes, once), then"
say "copies the files, runs the setup checks and starts the session. Next, in this order, from study/:"
step "bash pi/wizard.sh plans/pi5-fullcell.json    # the fan pilot (#29): one full cell, 15-25 min under load"
step "bash pi/wizard.sh plans/pi5-speedtest.json   # then the speed test (#25)"
note "Its stage 2 offers this host and user from pi/.env: press Enter to keep them."
note "Its stage 1 says 'Active Cooler': your fan on the FAN socket is what it checks for."
if confirm "Start the pilot now?"; then
  exec bash "$STUDY/pi/wizard.sh" plans/pi5-fullcell.json
fi
finish
say "Next: bash pi/wizard.sh plans/pi5-fullcell.json"
}

run_wizard "$@"; exit
